import { AsyncLocalStorage } from "node:async_hooks"

const als = new AsyncLocalStorage<{ requestId: string }>()

function log(msg: string) {
    console.log(`[${als.getStore()?.requestId ?? "-"}] ${msg}`)   // store'ni istalgan joydan o'qiymiz
}

async function handle(requestId: string) {
    await als.run({ requestId }, async () => {   // shu callback va undan boshlangan hamma ish requestId'ni ko'radi
        log("boshlandi")
        await new Promise(r => setTimeout(r, 10))
        log("tugadi")
    })
}

