@Injectable()
class ImportJob {
    private running = false
    private calls = 0
    private release!: () => void
    private gate = new Promise<void>(resolve => (this.release = resolve))   // uzoq ishni qo'lda tugatamiz
    private skipped!: () => void
    threeSkipped = new Promise<void>(resolve => (this.skipped = resolve))

    constructor(private readonly registry: SchedulerRegistry) {}

    @Interval("import", 10)
    async run() {
        this.calls++
        if (this.running) {
            console.log("o'tkazib yuborildi (oldingisi hali ishlayapti)")
            if (this.calls === 4) { this.registry.deleteInterval("import"); this.skipped() }
            return
        }
        this.running = true
        console.log("import boshlandi")
        await this.gate
        console.log("import tugadi")
        this.running = false
    }

    finish() { this.release() }
}

