    private reached!: () => void
    fourRuns = new Promise<void>(resolve => (this.reached = resolve))

    constructor(private readonly registry: SchedulerRegistry) {}

    @Interval("sync", 10)
    async sync() {
        this.runs++
        if (this.runs === 4) { this.registry.deleteInterval("sync"); this.reached() }
        if (this.runs === 2) throw new Error("tashqi API javob bermadi")
    }
}

@Module({ imports: [ScheduleModule.forRoot()], providers: [SyncJob] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const job = app.get(SyncJob)
    await job.fourRuns
    console.log("2-ishga tushish xato berdi, lekin jami ishga tushishlar:", job.runs)
    await app.close()
}
main()

