import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { Cron, ScheduleModule, SchedulerRegistry } from "@nestjs/schedule"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))

@Injectable()
class Jobs {
    safe = 0
    unsafe = 0

    @Cron("0 0 1 1 *", { name: "safe", waitForCompletion: true })
    async safeJob() { this.safe++; await sleep(30) }

    @Cron("0 0 1 1 *", { name: "unsafe" })
    async unsafeJob() { this.unsafe++; await sleep(30) }
}

@Module({ imports: [ScheduleModule.forRoot()], providers: [Jobs] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const registry = app.get(SchedulerRegistry)
    for (const name of ["safe", "unsafe"]) {
        const job = registry.getCronJob(name)
        await Promise.all([job.fireOnTick(), job.fireOnTick(), job.fireOnTick()])    // 3 ta bir vaqtda
    }
    const jobs = app.get(Jobs)
    console.log("waitForCompletion: true  ->", jobs.safe, "marta")
    console.log("waitForCompletion: false ->", jobs.unsafe, "marta")
    await app.close()
}
