@Injectable()
class Poller {
    ticks = 0
    private reached!: () => void
    twoTicks = new Promise<void>(resolve => (this.reached = resolve))

    @Interval("poll", 15)
    poll() { if (++this.ticks === 2) this.reached() }
}

@Module({ imports: [ScheduleModule.forRoot()], providers: [Poller] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const registry = app.get(SchedulerRegistry)
