    console.log("registry qaytargan tur:", timer.constructor.name)
    clearInterval(timer)                                   // oddiy Node.js usuli
    const before = app.get(Poller).ticks
    await new Promise(r => setTimeout(r, 80))
    console.log("clearInterval'dan keyin yangi tick:", app.get(Poller).ticks - before)
