@Injectable()
class InMemoryQueue {
    private jobs: { id: number; data: { email: string } }[] = []
    private nextId = 1
    processed: string[] = []
    add(data: { email: string }) {
        const job = { id: this.nextId++, data }
        this.jobs.push(job)
        return job.id
    }
    // Worker: alohida jarayon deb tasavvur qiling — navbatni bo'shatadi
    async drain() {
        for (const job of this.jobs.splice(0)) this.processed.push(`#${job.id} → ${job.data.email}`)
    }
}

