import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { EventEmitter2, EventEmitterModule, OnEvent } from "@nestjs/event-emitter"

@Injectable() class Mailer { @OnEvent("order.created") send(id: number) { console.log("📧 xat yuborildi: buyurtma", id) } }

@Injectable()
class OrdersService {
    constructor(private readonly events: EventEmitter2) {}
    async create(id: number, fail: boolean) {
        const pending: [string, unknown][] = []
        try {
            pending.push(["order.created", id])                     // hozircha yubormaymiz
            if (fail) throw new Error("DB xatosi")
            console.log(`buyurtma ${id} saqlandi (commit)`)
            for (const [name, payload] of pending) this.events.emit(name, payload)
        } catch (e) { console.log(`buyurtma ${id} rollback — hodisalar tashlab yuborildi`) }
    }
}
@Module({ imports: [EventEmitterModule.forRoot()], providers: [Mailer, OrdersService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.init()
    await app.get(OrdersService).create(1, false)
    await app.get(OrdersService).create(2, true)
    await app.close()
}
main()

