import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { EventEmitter2, EventEmitterModule, OnEvent } from "@nestjs/event-emitter"

class Order {
    private events: { name: string; payload: object }[] = []
    status = "new"
    constructor(public id: number) {}
    pay() { this.status = "paid"; this.events.push({ name: "order.paid", payload: { id: this.id, what: "to'landi" } }) }
    ship() { this.status = "shipped"; this.events.push({ name: "order.shipped", payload: { id: this.id, what: "jo'natildi" } }) }
    pullEvents() { const e = this.events; this.events = []; return e }
}
@Injectable() class OrdersRepo {
    constructor(private emitter: EventEmitter2) {}
    save(o: Order) {
        console.log(`saqlandi: #${o.id} (${o.status})`)
        for (const e of o.pullEvents()) this.emitter.emit(e.name, e.payload)
    }
}
@Injectable() class Notifier { @OnEvent("order.*") on(p: { id: number; what: string }) { console.log(`  xabar: buyurtma #${p.id} ${p.what}`) } }
@Module({ imports: [EventEmitterModule.forRoot({ wildcard: true })], providers: [OrdersRepo, Notifier] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const o = new Order(12)
    o.pay(); o.ship()
    console.log("saqlashdan oldin hech narsa chiqmadi")
    app.get(OrdersRepo).save(o)
    await app.close()
}
main()

