type Envelope<T> = { id: string; type: string; occurredAt: string; payload: T }
let seq = 0
const envelope = <T>(type: string, payload: T): Envelope<T> => ({ id: `evt-${++seq}`, type, occurredAt: "2024-10-01T10:00:00Z", payload })
@Injectable() class Audit { @OnEvent("**") log(e: Envelope<unknown>) { console.log(`${e.id} | ${e.type} | ${e.occurredAt} |`, e.payload) } }
@Module({ imports: [EventEmitterModule.forRoot({ wildcard: true })], providers: [Audit] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const e = app.get(EventEmitter2)
    e.emit("user.registered", envelope("user.registered", { id: 1 }))
    e.emit("order.paid", envelope("order.paid", { id: 51 }))
    await app.close()
}
