@Injectable() class Wallet {
    balance = 0
    private processed = new Set<string>()
    @OnEvent("payment.received")
    on(e: { eventId: string; amount: number }) {
        if (this.processed.has(e.eventId)) return console.log(`  ${e.eventId}: takroriy, o'tkazib yuborildi`)
        this.processed.add(e.eventId)
        this.balance += e.amount
        console.log(`  ${e.eventId}: +${e.amount}`)
    }
}
@Module({ imports: [EventEmitterModule.forRoot()], providers: [Wallet] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const e = app.get(EventEmitter2)
    for (const id of ["p-1", "p-2", "p-1"]) e.emit("payment.received", { eventId: id, amount: 50000 })
    console.log("Balans:", app.get(Wallet).balance)
    await app.close()
}
main()

