@Injectable()
class Mailer {
    send(to: string) { throw new Error(`SMTP ulanmadi (${to})`) }
}

@Injectable()
class MailListener {
    constructor(private readonly mailer: Mailer) {}
    @OnEvent("order.created")
    on(email: string) { this.mailer.send(email) }
}

@Injectable()
class OrdersService {
    constructor(private readonly mailer: Mailer, private readonly events: EventEmitter2) {}

    createDirect(email: string) {
        this.mailer.send(email)      // xato shu yerda to'xtatadi
        return "buyurtma yaratildi"
    }

    createWithEvent(email: string) {
        this.events.emit("order.created", email)   // xato listener ichida qoladi
        return "buyurtma yaratildi"
    }
}

@Module({ imports: [EventEmitterModule.forRoot()], providers: [Mailer, MailListener, OrdersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const orders = app.get(OrdersService)
    try { console.log(orders.createDirect("ali@mail.uz")) } catch (e) { console.log("to'g'ridan-to'g'ri:", (e as Error).message) }
    console.log("hodisa orqali:", orders.createWithEvent("ali@mail.uz"))
    await app.close()
}
