@Injectable()
class ProductsService {
    constructor(@Inject(CACHE_MANAGER) private readonly cache: Cache) {}
    async find(id: string) {
        const key = `product:${id}`
        const cached = await this.cache.get(key)
        if (cached) return { ...cached as object, source: "kesh" }
        dbHits++
        await new Promise(r => setTimeout(r, 20)) // sekin baza
        const product = { id, name: `Mahsulot ${id}` }
        await this.cache.set(key, product, 60_000)
        return { ...product, source: "baza" }
    }
}

@Controller("products")
class ProductsController {
    constructor(private readonly s: ProductsService) {}
    @Get(":id") find(@Param("id") id: string) { return this.s.find(id) }
}

@Module({ imports: [CacheModule.register()], controllers: [ProductsController], providers: [ProductsService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/products/7")
    await http.get("/products/7")
    await http.get("/products/8")
    console.log("bazaga murojaatlar:", dbHits)
    await http.close()
}
main()

