import { CACHE_MANAGER } from "@nestjs/cache-manager"
import { Inject, Injectable } from "@nestjs/common"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

@Injectable()
class CatalogService {
    constructor(@Inject(CACHE_MANAGER) private readonly cache: { get(k: string): Promise<unknown>; set(k: string, v: unknown, ttl?: number): Promise<void> }) {}
    async categories() {
        const hit = await this.cache.get("cats")
        if (hit) return hit
        const fresh = ["Ichimlik", "Non"]
        await this.cache.set("cats", fresh, 300_000)
        return fresh
    }
}

async function main() {
    const store = new Map<string, unknown>()
    const sets: unknown[] = []
    const m = await Test.createTestingModule({
        providers: [CatalogService, { provide: CACHE_MANAGER, useValue: { get: async (k: string) => store.get(k), set: async (k: string, v: unknown, ttl?: number) => { store.set(k, v); sets.push([k, ttl]) } } }],
    }).compile()
    const s = m.get(CatalogService)
    await s.categories(); await s.categories()
    assert.deepEqual(sets, [["cats", 300_000]])
    console.log("✔ kesh bir marta to'ldirildi, TTL 5 daqiqa")
}
main()

