        v === undefined ? this.stats.miss++ : this.stats.hit++
        return v
    }
    async run() {
        await this.cache.set("a", 1)
        for (const k of ["a", "a", "b", "a", "c"]) await this.get(k)
        const total = this.stats.hit + this.stats.miss
        console.log(this.stats, `hit ratio: ${Math.round((this.stats.hit / total) * 100)}%`)
    }
}
