import { CacheInterceptor, CacheModule } from "@nestjs/cache-manager"

@Injectable()
class SearchCacheInterceptor extends CacheInterceptor {
    trackBy(context: ExecutionContext) {
        const req = context.switchToHttp().getRequest()
        // Standart holatda POST keshlanmaydi; bu yerda kalit — URL + body
        return `${req.url}:${JSON.stringify(req.body)}`
    }
}

let searches = 0

@Controller("search")
@UseInterceptors(SearchCacheInterceptor)
class SearchController {
    @Post() search(@Body() body: { q: string }) { return { q: body.q, searches: ++searches } }
}

@Module({ imports: [CacheModule.register({ ttl: 60_000 })], controllers: [SearchController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/search", { q: "osh" })
    await http.post("/search", { q: "osh" })
    await http.post("/search", { q: "manti" })
    await http.close()
}
main()

