function port(raw: string | undefined, def = 3000) {
    if (raw === undefined) return def
    const n = Number(raw)
    if (!Number.isInteger(n) || n < 1 || n > 65535) throw new Error(`PORT noto'g'ri: "${raw}"`)
    return n
}
for (const raw of [undefined, "8080", "80a", "70000"]) {
    try { console.log(String(raw).padEnd(9), "→", port(raw)) } catch (e) { console.log(String(raw).padEnd(9), "→", (e as Error).message) }
}

