const mailConfig = registerAs("mail", () => ({ host: "smtp.shop.uz", port: 587 }))

type MailOptions = { host: string; port: number }

@Injectable()
class MailService {
    constructor(@Inject("MAIL_OPTIONS") private readonly options: MailOptions) {}
    info() { return `SMTP ${this.options.host}:${this.options.port}` }
}

@Module({})
class MailModule {
    static registerAsync(o: { imports?: any[]; inject?: any[]; useFactory: (...args: any[]) => MailOptions }): DynamicModule {
        return {
            module: MailModule,
            imports: o.imports,
            providers: [{ provide: "MAIL_OPTIONS", useFactory: o.useFactory, inject: o.inject }, MailService],
            exports: [MailService],
        }
    }
}

@Module({
    imports: [
        ConfigModule.forRoot({ ignoreEnvFile: true }),
        MailModule.registerAsync(mailConfig.asProvider()),   // imports + useFactory + inject tayyor
    ],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log(app.get(MailService).info())
