import { Controller, Module, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"
import { diskStorage } from "multer"
import { mkdtempSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"
import { extname } from "node:path"

const uploadDir = mkdtempSync(`${tmpdir()}/uploads-`)   // amalda: "./uploads"

@Controller("upload")
class UploadController {
    @Post("image")
    @UseInterceptors(FileInterceptor("file", {
        storage: diskStorage({
            destination: uploadDir,
            filename: (_req, file, cb) => {
                // Nomlar bir xil bo'lib qolmasligi uchun vaqt va tasodifiy son qo'shamiz
                const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9)
                cb(null, uniqueSuffix + extname(file.originalname))
            },
        }),
    }))
    uploadFile(@UploadedFile() file: Express.Multer.File) {
        return {
            message: "Yuklandi",
            asl: file.originalname,
            nomiMosmi: /^\d+-\d+\.png$/.test(file.filename),   // 1729250000000-123456789.png
        }
    }
}

@Module({ controllers: [UploadController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const form = new FormData()
    form.append("file", new Blob(["PNG..."], { type: "image/png" }), "logo.png")
    const res = await fetch((await http.app.getUrl()) + "/upload/image", { method: "POST", body: form })
    console.log("POST /upload/image →", res.status, await res.text())
    await http.close()
    rmSync(uploadDir, { recursive: true })
}
main()

