import { Controller, FileValidator, Module, ParseFilePipe, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

class SafeNameValidator extends FileValidator {
    constructor() { super({}) }
    isValid(file?: Express.Multer.File) { return !!file && /^[\w.-]+$/.test(file.originalname) }
    buildErrorMessage() { return "Fayl nomida faqat harf, raqam, nuqta, _ va - bo'lsin" }
}

@Controller("upload")
class UploadController {
    @Post()
    @UseInterceptors(FileInterceptor("file"))
    upload(@UploadedFile(new ParseFilePipe({ validators: [new SafeNameValidator()] })) f: Express.Multer.File) {
        return { ok: f.originalname }
    }
}

@Module({ controllers: [UploadController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const url = (await http.app.getUrl()) + "/upload"
    for (const name of ["report_2026.pdf", "mening fayl(1).pdf"]) {
        const form = new FormData()
