function pngSize(buf: Buffer) {
    if (buf.subarray(0, 8).toString("hex") !== "89504e470d0a1a0a") throw new BadRequestException("PNG emas")
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) }
}
@Controller("banners") class B {
    @Post() @UseInterceptors(FileInterceptor("file"))
    up(@UploadedFile() f: Express.Multer.File) {
        const { width, height } = pngSize(f.buffer)
        if (width < 1200) throw new BadRequestException(`Kenglik kamida 1200px bo'lsin (berildi ${width}px)`)
        return { width, height }
    }
}
@Module({ controllers: [B] }) class AppModule {}

const fakePng = (w: number, h: number) => {
    const b = Buffer.alloc(24)
    Buffer.from("89504e470d0a1a0a0000000d49484452", "hex").copy(b)
    b.writeUInt32BE(w, 16); b.writeUInt32BE(h, 20)
    return b
}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    for (const [w, h] of [[1920, 600], [800, 600]]) {
        const form = new FormData(); form.append("file", new Blob([fakePng(w, h)]), "banner.png")
        const res = await fetch(base + "/banners", { method: "POST", body: form })
        console.log(`${w}x${h} →`, res.status, await res.text())
    }
    await http.close()
}
main()

