import { BadRequestException, Controller, Module, Post, UploadedFiles, UseInterceptors } from "@nestjs/common"
import { FileFieldsInterceptor } from "@nestjs/platform-express"

type Files = { avatar?: Express.Multer.File[]; document?: Express.Multer.File[] }
const RULES: Record<string, RegExp> = { avatar: /^image\/(png|jpeg)$/, document: /^application\/pdf$/ }
@Controller("profile") class P {
    @Post() @UseInterceptors(FileFieldsInterceptor([{ name: "avatar", maxCount: 1 }, { name: "document", maxCount: 1 }]))
    up(@UploadedFiles() files: Files) {
        for (const [field, list] of Object.entries(files)) {
            for (const f of list ?? []) if (!RULES[field].test(f.mimetype)) throw new BadRequestException(`${field}: ${f.mimetype} ruxsat etilmagan`)
        }
        return { ok: Object.keys(files) }
    }
}
@Module({ controllers: [P] }) class AppModule {}

