        form.append("document", new Blob(["d"], { type: docType }), "doc")
        const res = await fetch(base + "/profile", { method: "POST", body: form })
        console.log(`document=${docType} →`, res.status, await res.text())
    }
    await send("application/pdf")
    await send("application/msword")
    await http.close()
}
