import { CanActivate, Controller, ExecutionContext, Injectable, Module, Post, UnauthorizedException, UploadedFile, UseGuards, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

let filterCalls = 0

@Injectable()
class TokenGuard implements CanActivate {
    canActivate(context: ExecutionContext) {
        const token = context.switchToHttp().getRequest().headers["authorization"]
        if (token !== "Bearer sirli-token") throw new UnauthorizedException("Token kerak")
        return true
    }
}

@Controller("files")
class FilesController {
    @Post()
    @UseGuards(TokenGuard)   // guard interceptor'dan oldin ishlaydi
    @UseInterceptors(FileInterceptor("file", { fileFilter: (_req, _file, cb) => { filterCalls++; cb(null, true) } }))
    upload(@UploadedFile() file: Express.Multer.File) { return { saqlandi: file.originalname } }
}

@Module({ controllers: [FilesController] })
class AppModule {}

