import { mkdtempSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"

const dir = mkdtempSync(`${tmpdir()}/disk-`)
const storage = diskStorage({ destination: dir })

@Controller("disk")
class DiskController {
    // 1) buffer yo'q: magic number tekshirib bo'lmaydi
    @Post("strict")
    @UseInterceptors(FileInterceptor("file", { storage }))
    strict(@UploadedFile(new ParseFilePipe({ validators: [new FileTypeValidator({ fileType: "text/plain" })] })) f: Express.Multer.File) {
        return { ok: f.originalname }
    }

    // 2) fallbackToMimetype: buffer bo'lmasa so'rovdagi mimetype'ga qaraydi
    @Post("fallback")
    @UseInterceptors(FileInterceptor("file", { storage }))
    fallback(@UploadedFile(new ParseFilePipe({ validators: [new FileTypeValidator({ fileType: "text/plain", fallbackToMimetype: true })] })) f: Express.Multer.File) {
        return { ok: f.originalname }
    }
}

