import { Controller, Module, ParseFilePipeBuilder, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

const imagePipe = new ParseFilePipeBuilder()
    .addFileTypeValidator({ fileType: "png", skipMagicNumbersValidation: true })   // "image/png" ichida "png" bor
    .addMaxSizeValidator({ maxSize: 1000 })
    .build({ fileIsRequired: false })

@Controller("avatar")
class AvatarController {
    @Post()
    @UseInterceptors(FileInterceptor("file"))
    upload(@UploadedFile(imagePipe) file?: Express.Multer.File) {
        return { avatar: file?.originalname ?? "yuklanmadi" }
    }
}

@Module({ controllers: [AvatarController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const cases: [string, number, string][] = [["rasm.png", 500, "image/png"], ["rasm.gif", 500, "image/gif"], ["katta.png", 5000, "image/png"]]
    for (const [name, size, type] of cases) {
        const form = new FormData()
        form.append("file", new Blob([new Uint8Array(size)], { type }), name)
        const res = await fetch(base + "/avatar", { method: "POST", body: form })
        console.log(name.padEnd(10), "→", res.status, await res.text())
    }
    const empty = await fetch(base + "/avatar", { method: "POST", body: new FormData() })
    console.log("faylsiz".padEnd(10), "→", empty.status, await empty.text())
    await http.close()
}
main()

