import { Controller, Module, ParseFilePipe, Post, UploadedFile, UseInterceptors } from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"

const onlyImages = (_req: unknown, file: Express.Multer.File, cb: (error: Error | null, accept: boolean) => void) =>
    cb(null, file.mimetype.startsWith("image/"))

@Controller("silent")
