import { Controller, Get, Module, Param, Res, StreamableFile } from "@nestjs/common"
import type { Response } from "express"
import { createReadStream, mkdtempSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const dir = mkdtempSync(join(tmpdir(), "dl-"))
writeFileSync(join(dir, "shartnoma.txt"), "Shartnoma matni\n")

@Controller("download")
class DownloadController {
    @Get(":name")
    download(@Param("name") name: string, @Res({ passthrough: true }) res: Response) {
        res.set({
            "Content-Type": "text/plain; charset=utf-8",
            "Content-Disposition": `attachment; filename="${name}"`,
        })
        return new StreamableFile(createReadStream(join(dir, name)))   // oqim: xotiraga to'liq yuklanmaydi
    }
}

@Module({ controllers: [DownloadController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const res = await fetch((await http.app.getUrl()) + "/download/shartnoma.txt")
    console.log("Content-Disposition:", res.headers.get("content-disposition"))
    console.log("Tana:", JSON.stringify(await res.text()))
    await http.close()
}
main()

