@Injectable() class DataMeta implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const req = ctx.switchToHttp().getRequest()
        return next.handle().pipe(map(data => ({ data, meta: { path: req.url, count: Array.isArray(data) ? data.length : 1, apiVersion: "1.4" } })))
    }
}
