import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, Version, VersioningType } from "@nestjs/common"
import { APP_INTERCEPTOR } from "@nestjs/core"

@Injectable() class VersionHeader implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const v = Reflect.getMetadata("__version__", ctx.getHandler()) ?? Reflect.getMetadata("__version__", ctx.getClass()) ?? "none"
        ctx.switchToHttp().getResponse().setHeader("X-API-Version", String(v))
        return next.handle()
    }
}
