export class JsonLogger implements LoggerService {
    log(message: unknown, context?: string) {
        console.log(JSON.stringify({ level: "info", context, message }))
    }
    error(message: unknown, stack?: string, context?: string) {
        console.error(JSON.stringify({ level: "error", context, message, stack }))
    }
    warn(message: unknown, context?: string) {
        console.warn(JSON.stringify({ level: "warn", context, message }))
    }
}

export class SentryLogger extends ConsoleLogger {
    error(message: unknown, ...rest: any[]) {
