import { Body, Controller, createParamDecorator, ExecutionContext, Get, Module, Post, Res, UnauthorizedException } from "@nestjs/common"
import cookieParser from "cookie-parser"
import type { Request, Response } from "express"

const Cookies = createParamDecorator((name: string, ctx: ExecutionContext) => ctx.switchToHttp().getRequest<Request>().cookies?.[name])
const tokens = new Map<string, string>()      // token → foydalanuvchi

@Controller("auth")
class AuthController {
    @Post("login")
    login(@Body() dto: { user: string }, @Res({ passthrough: true }) res: Response) {
        const token = `tok-${tokens.size + 1}`
        tokens.set(token, dto.user)
        res.cookie("token", token, { httpOnly: true, sameSite: "lax" })
        return { ok: true }
    }
    @Get("me")
    me(@Cookies("token") token?: string) {
        const user = token && tokens.get(token)
        if (!user) throw new UnauthorizedException()
        return { user }
    }
    @Post("logout")
    logout(@Cookies("token") token: string, @Res({ passthrough: true }) res: Response) {
        tokens.delete(token)
        res.clearCookie("token")
        return { ok: true }
    }
}

@Module({ controllers: [AuthController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.use(cookieParser()))
    const cookie = { Cookie: (await http.post("/auth/login", { user: "ali" })).headers.getSetCookie()[0].split(";")[0] }
    await http.get("/auth/me", cookie)
    await http.post("/auth/logout", undefined, cookie)
    await http.get("/auth/me", cookie)
    await http.close()
}
main()

