const USERS = [{ id: 1, name: "Ali", password: "s3cret" }]

@Controller("auth")
class AuthController {
    @Post("login")
    login(@Body() dto: { name: string; password: string }, @Req() req: Request) {
        const user = USERS.find(u => u.name === dto.name && u.password === dto.password)
        if (!user) throw new UnauthorizedException("login yoki parol noto'g'ri")
        req.session.userId = user.id
        return { ok: true }
    }
    @Get("me")
    me(@Req() req: Request) {
        const user = USERS.find(u => u.id === req.session.userId)
        if (!user) throw new UnauthorizedException()
        return { id: user.id, name: user.name }
    }
}

