import { Controller, createParamDecorator, ExecutionContext, Get, Module, Post, Req } from "@nestjs/common"
import session from "express-session"
import type { Request } from "express"

interface SessionUser { id: number; name: string; role: string }

const CurrentUser = createParamDecorator((field: keyof SessionUser | undefined, ctx: ExecutionContext) => {
    const user: SessionUser | undefined = ctx.switchToHttp().getRequest<Request>().session["user"]
    return field ? user?.[field] : user
})

