@HealthCheck({ swaggerDocumentation: false })        // Swagger sxemasini qo'shmaydi

@Injectable()
export class RedisHealthIndicator {
    constructor(
        private readonly indicator: HealthIndicatorService,
        private readonly redis: RedisClient,
    ) {}

    async isHealthy(key: string) {
        const check = this.indicator.check(key)       // sessiya: natija kaliti — key
        try {
            const pong = await this.redis.ping()
            return check.up({ pong })                  // { [key]: { pong, status: "up" } }
        } catch (err) {
            return check.down({ message: (err as Error).message })
        }
    }
