import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { HealthCheck, HealthCheckService, HealthIndicatorService, TerminusModule } from "@nestjs/terminus"
import { createServer } from "node:http"
import type { AddressInfo } from "node:net"

let onAborted = () => {}
const upstream = createServer((req, res) => {
    req.on("close", () => onAborted())   // javob hech qachon yuborilmaydi
})
let upstreamUrl = ""

@Injectable()
class UpstreamIndicator {
    constructor(private indicator: HealthIndicatorService) {}

    isHealthy(key: string) {
        return this.indicator
            .check(key)
            .attempt(async ({ signal }) => {
                await fetch(upstreamUrl, { signal })   // signal abort bo'lsa fetch ham to'xtaydi
            })
            .withTimeout(100)
    }
}

@Controller("health")
class HealthController {
    constructor(private health: HealthCheckService, private up: UpstreamIndicator) {}

    @Get()
    @HealthCheck()
    check() {
        return this.health.check([() => this.up.isHealthy("upstream")])
    }
}

@Module({ imports: [TerminusModule], controllers: [HealthController], providers: [UpstreamIndicator] })
class AppModule {}

async function main() {
    await new Promise<void>(resolve => upstream.listen(0, "127.0.0.1", resolve))
    upstreamUrl = `http://127.0.0.1:${(upstream.address() as AddressInfo).port}`
    const aborted = new Promise<void>(resolve => (onAborted = resolve))
    const http = await testApp(AppModule)
    const res = await fetch((await http.app.getUrl()) + "/health")
    console.log("health javobi:", res.status)
    await aborted   // upstream server so'rov uzilganini ko'rdi
    console.log("upstream so'rovi bekor qilindi")
    await http.close()
    upstream.close()
}
main()

