import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, SetMetadata } from "@nestjs/common"
import { APP_GUARD, Reflector } from "@nestjs/core"
import { HealthCheck, HealthCheckService, TerminusModule } from "@nestjs/terminus"

const Public = () => SetMetadata("isPublic", true)

@Injectable()
class AuthGuard implements CanActivate {
    constructor(private reflector: Reflector) {}

    canActivate(context: ExecutionContext) {
        const isPublic = this.reflector.getAllAndOverride<boolean>("isPublic", [context.getHandler(), context.getClass()])
        if (isPublic) return true
        return context.switchToHttp().getRequest().headers.authorization === "Bearer demo"
    }
}

@Controller("health")
class HealthController {
    constructor(private health: HealthCheckService) {}

    @Public()
    @Get()
    @HealthCheck()
    check() {
        return this.health.check([])
    }
}

