async function main() {
    const calls: Array<[string, number]> = []
    const fakeHealth = {
        // indikator funksiyalarini ishga tushirib, natijalarni qaytaradi
        check: async (fns: Array<() => unknown>) => ({ status: "ok", results: await Promise.all(fns.map(fn => fn())) }),
    }
    const fakeMemory = {
