            calls.push([key, limit])
            return { [key]: { status: "up" } }
        },
    }
    const moduleRef = await Test.createTestingModule({
        controllers: [HealthController],
        providers: [
            { provide: HealthCheckService, useValue: fakeHealth },
            { provide: MemoryHealthIndicator, useValue: fakeMemory },
        ],
    }).compile()

    const result = await moduleRef.get(HealthController).check()
    console.log(JSON.stringify(result))
    console.log("checkHeap chaqiruvlari:", JSON.stringify(calls))
}
