import { Controller, Get, Injectable, Module } from "@nestjs/common"
import { HealthCheck, HealthCheckService, HealthIndicatorService, TerminusModule } from "@nestjs/terminus"

@Injectable()
class Flaky {
    results = [true, false, false, true, false, false, false]   // har bir probe uchun holat
    next() {
        return this.results.shift() ?? true
    }
}

@Controller("health")
class HealthController {
    constructor(private health: HealthCheckService, private indicator: HealthIndicatorService, private flaky: Flaky) {}

    @Get()
    @HealthCheck()
    check() {
        const check = this.indicator.check("service")
        return this.health.check([() => (this.flaky.next() ? check.up() : check.down())])
    }
}

@Module({ imports: [TerminusModule], controllers: [HealthController], providers: [Flaky] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const failureThreshold = 3
    let failures = 0
    for (let probe = 1; probe <= 7; probe++) {
        const res = await fetch(base + "/health")
        failures = res.ok ? 0 : failures + 1
        console.log(`probe ${probe}: ${res.status}, ketma-ket xato: ${failures}`)
        if (failures >= failureThreshold) {
            console.log("-> konteyner qayta ishga tushiriladi")
            break
        }
    }
    await http.close()
}
main()

