// 3. concat: avval boshlang'ich holat, keyin jonli yangilanishlar
concat(of({ type: "snapshot", data: snapshot }), updates$)

// 4. filter: har bir klientga faqat unga tegishli hodisalar
bus$.pipe(filter(e => e.userId === userId))

// 5. merge: hodisalar + heartbeat
merge(events$, interval(20_000).pipe(map(() => ({ comment: "ping" }))))

