import { Controller, MessageEvent, Module, Sse } from "@nestjs/common"
import { Observable, interval, map, take } from "rxjs"

@Controller("clock")
class ClockController {
    @Sse("ticks")
    ticks(): Observable<MessageEvent> {
        // har 20 ms da bitta hodisa; take(3) — uchtadan keyin oqim tugaydi
        return interval(20).pipe(
            take(3),
            map(n => ({ data: { tick: n + 1 } })),
        )
    }
}

@Module({ controllers: [ClockController] })
class AppModule {}

async function readEvents(res: Response, count: number) {
    let text = ""
    for await (const chunk of res.body as any) {
        text += Buffer.from(chunk).toString()
        if (text.split("\n\n").length > count) break   // kerakli hodisalar soniga yetdik
    }
    return text.trim().split("\n\n").slice(0, count).join("\n\n")
}

