import { Controller, Headers, Injectable, MessageEvent, Module, Sse } from "@nestjs/common"
import { Observable, Subject, concat, from } from "rxjs"

@Injectable()
class FeedService {
    private readonly history: MessageEvent[] = []
    private readonly live = new Subject<MessageEvent>()

    publish(text: string) {
        const event = { id: String(this.history.length + 1), data: { text } }
        this.history.push(event)
        this.live.next(event)
    }

    stream(lastId?: string): Observable<MessageEvent> {
        const missed = this.history.filter(event => Number(event.id) > Number(lastId ?? 0))
        return concat(from(missed), this.live)   // avval o'tkazib yuborilganlar, keyin jonli oqim
    }
}

@Controller("feed")
class FeedController {
    constructor(private readonly feed: FeedService) {}

    @Sse()
    stream(@Headers("last-event-id") lastId?: string) {
        return this.feed.stream(lastId)
    }
}

@Module({ controllers: [FeedController], providers: [FeedService] })
