@Injectable()
class MessageBus {
    private readonly bus = new Subject<{ user: string; text: string }>()

    send(user: string, text: string) {
        this.bus.next({ user, text })
    }

    forUser(user: string): Observable<MessageEvent> {
        return this.bus.pipe(
            filter(message => message.user === user),
            map(message => ({ type: "message", data: { text: message.text } })),
        )
    }
}

