function parseEvent(block: string) {
    const event: { type: string; id?: string; data: string[] } = { type: "message", data: [] }
    for (const line of block.split("\n")) {
        const [field, ...rest] = line.split(": ")
        const value = rest.join(": ")
        if (field === "event") event.type = value
        else if (field === "id") event.id = value
        else if (field === "data") event.data.push(value)
    }
    return { type: event.type, id: event.id, data: event.data.join("\n") }
}

async function main() {
    const http = await testApp(AppModule)
    const text = await (await fetch((await http.app.getUrl()) + "/market")).text()
    for (const block of text.trim().split("\n\n")) console.log(parseEvent(block))
    await http.close()
}
