import { Controller, Get, Headers, HttpStatus, Module, Res, StreamableFile } from "@nestjs/common"
import type { Response } from "express"
import { createReadStream, mkdtempSync, statSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const path = join(mkdtempSync(join(tmpdir(), "files-")), "alphabet.txt")
writeFileSync(path, "abcdefghijklmnopqrstuvwxyz")

@Controller("media")
class MediaController {
    @Get("alphabet")
    alphabet(@Headers("range") range: string | undefined, @Res({ passthrough: true }) res: Response) {
        const size = statSync(path).size
        res.set("Accept-Ranges", "bytes")
        if (!range) return new StreamableFile(createReadStream(path), { type: "text/plain", length: size })

        const [from, to] = range.replace("bytes=", "").split("-")
        const start = Number(from)
        const end = to ? Number(to) : size - 1
        res.status(HttpStatus.PARTIAL_CONTENT).set("Content-Range", `bytes ${start}-${end}/${size}`)
        return new StreamableFile(createReadStream(path, { start, end }), { type: "text/plain", length: end - start + 1 })
    }
}

@Module({ controllers: [MediaController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const res = await http.get("/media/alphabet", { Range: "bytes=2-6" })
    console.log("Content-Range:", res.headers.get("content-range"))
    await http.get("/media/alphabet")
    await http.close()
}
main()

import { Controller, Get, Headers, HttpStatus, Module, Res, StreamableFile } from "@nestjs/common"
import type { Response } from "express"
import { createReadStream, mkdtempSync, statSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

const path = join(mkdtempSync(join(tmpdir(), "files-")), "alphabet.txt")
writeFileSync(path, "abcdefghijklmnopqrstuvwxyz")

@Controller("media")
class MediaController {
    @Get("alphabet")
    alphabet(@Headers("range") range: string | undefined, @Res({ passthrough: true }) res: Response) {
        const size = statSync(path).size
        const [from, to] = (range ?? `bytes=0-${size - 1}`).replace("bytes=", "").split("-")
        const start = Number(from)
        const end = to ? Number(to) : size - 1
        if (start >= size || end >= size || start > end) {
            res.status(HttpStatus.REQUESTED_RANGE_NOT_SATISFIABLE).set("Content-Range", `bytes */${size}`)
            return "Oraliq noto'g'ri"
        }
        return new StreamableFile(createReadStream(path, { start, end }), { type: "text/plain" })
    }
}

@Module({ controllers: [MediaController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const res = await http.get("/media/alphabet", { Range: "bytes=100-200" })
    console.log("Content-Range:", res.headers.get("content-range"))
