import { Controller, Get, Module } from "@nestjs/common"
import compression from "compression"
import { request } from "node:http"

@Controller("products")
class ProductsController {
    @Get()
    list() {
        return Array.from({ length: 200 }, (_, i) => ({ id: i + 1, name: `Mahsulot ${i + 1}` }))
    }
}

@Module({ controllers: [ProductsController] })
class AppModule {}

// Node fetch javobni o'zi ochib beradi, shuning uchun xom baytlarni http.request bilan o'qiymiz
function rawGet(url: string, encoding: string): Promise<{ headers: Record<string, any>; bytes: number }> {
    return new Promise(resolve => {
        request(url, { headers: { "Accept-Encoding": encoding } }, res => {
            let bytes = 0
            res.on("data", chunk => (bytes += chunk.length))
            res.on("end", () => resolve({ headers: res.headers, bytes }))
        }).end()
    })
}

async function main() {
    const http = await testApp(AppModule, app => app.use(compression()))
    const base = await http.app.getUrl()
    const plain = await rawGet(base + "/products", "identity")
    const gzip = await rawGet(base + "/products", "gzip")
    console.log("siqilmagan:", plain.bytes, "bayt, Content-Encoding:", plain.headers["content-encoding"] ?? "yo'q")
    console.log("gzip:", gzip.headers["content-encoding"], "| Vary:", gzip.headers["vary"], "| kichikroq:", gzip.bytes < plain.bytes / 3)
    await http.close()
}
main()

