class AppModule {}

function get(url: string, encoding: string): Promise<{ encoding?: string; bytes: number }> {
    return new Promise(resolve => {
        request(url, { headers: { "Accept-Encoding": encoding } }, res => {
            let bytes = 0
            res.on("data", chunk => (bytes += chunk.length))
            res.on("end", () => resolve({ encoding: res.headers["content-encoding"], bytes }))
        }).end()
    })
