        const result = await get(url, accept)
        sizes[accept] = result.bytes
        console.log(`Accept-Encoding: ${accept} -> ${result.encoding ?? "siqilmagan"}`)
    }
    console.log("br gzip dan kichik:", sizes["br"] < sizes["gzip"])
    await http.close()
